CREATE TABLE IF NOT EXISTS market_impact_cost_log (
    log_id SERIAL PRIMARY KEY,
    ordersmark TEXT,
    mic NUMERIC,
    calculated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS market_impact_cost_log (
    log_id SERIAL PRIMARY KEY,
    ordersmark TEXT,
    mic NUMERIC,
    calculated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

CREATE OR REPLACE PROCEDURE recalc_market_impact_cost()
LANGUAGE plpgsql
AS $$
DECLARE
    v_mkteffect REAL;
    v_recordvault TEXT;
    v_dealcount NUMERIC;
    v_dealquote NUMERIC;
    v_mic NUMERIC;
BEGIN
    -- Get current market factor from systemmonitoring
    SELECT mkteffect INTO v_mkteffect FROM systemmonitoring LIMIT 1;

    -- Process each new order
    FOR v_recordvault, v_dealcount, v_dealquote IN 
        SELECT recordvault, dealcount, dealquote 
        FROM orders 
        WHERE orderflow = 'New'
    LOOP
        -- Calculate MIC = dealcount * dealquote * mkteffect * 0.01
        v_mic := ROUND(CAST(v_dealcount * v_dealquote * v_mkteffect * 0.01 AS numeric), 4);

        -- Log the MIC value with timestamp
        INSERT INTO market_impact_cost_log (ordersmark, mic)
        VALUES (v_recordvault, v_mic);
    END LOOP;
END;
$$;
